(x, y, t) => {
  const wx1 = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.013-t*0.18)*14+Math.sin((x+y)*0.008+t*0.12)*10;
  const wy1 = Math.cos(y*0.018-t*0.22)*20+Math.sin(x*0.015+t*0.3)*14+Math.cos((x-y)*0.009-t*0.15)*10;
  const x1=x+wx1,y1=y+wy1;
  const wx2=Math.sin(y1*0.022+t*0.35)*8+Math.cos(x1*0.017-t*0.28)*6;
  const wy2=Math.cos(x1*0.02+t*0.32)*8+Math.sin(y1*0.019+t*0.4)*6;
  const sx=x1+wx2,sy=y1+wy2;
  const src=[
    [120+Math.sin(t*0.5)*90,60+Math.cos(t*0.35)*40,0.07,2.2,0],
    [360+Math.cos(t*0.45)*90,50+Math.sin(t*0.6)*35,0.09,1.8,1],
    [80+Math.sin(t*0.3+2)*70,180+Math.cos(t*0.5+1)*60,0.065,2.5,0.5],
    [400+Math.cos(t*0.55+3)*80,190+Math.sin(t*0.4+2)*50,0.08,2.0,1.2],
    [240+Math.sin(t*0.25+4)*130,100+Math.cos(t*0.45+3)*80,0.055,2.8,0.8],
    [240+Math.cos(t*0.3+5)*110,170+Math.sin(t*0.5)*70,0.075,1.9,0.3],
    [180+Math.sin(t*0.65+1)*60,120+Math.cos(t*0.75+2)*90,0.1,1.6,1.5],
    [300+Math.cos(t*0.4+2)*70,130+Math.sin(t*0.55+4)*60,0.085,2.1,0.7]
  ];
  let act=0,inh=0,harm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp+ph);
    inh+=Math.sin(d*f*0.6+t*sp*0.5+ph+1.8);
    harm+=Math.sin(d*f*1.3-t*sp*0.8+ph+3.1);
  }
  act/=8;inh/=8;harm/=8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95)*0.7+Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.sin((sx-sy)*0.08-t*1.8)*0.25+Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.2)*0.2)/2.45;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.055+ang*3+t*1.6)+Math.sin(dist*0.025-ang*6+t*0.8))*0.2;
  const lapAct=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.08+t*0.5)*0.6;
  const lapInh=Math.cos(sx*0.12-t*0.3)*Math.cos(sy*0.13+t*0.4)+Math.sin((sx-sy)*0.1-t*0.7)*0.5;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.22-t*0.8)*Math.cos(sy*0.18+t*0.6)*0.3)*1.8)*0.25;
  const fine=(Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.8)+Math.sin((sx-sy)*0.2+t*3)*0.4)*0.12;
  const reaction=Math.tanh((act-inh*0.65+bg*0.35+spiral+harm*0.2+lapAct*0.15-lapInh*0.1)*2.5);
  const blend=reaction*0.65+cell*0.2+fine*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,85,105],[25,135,120],[55,165,95],[145,185,70],[210,190,55],[225,145,60],[215,95,65],[185,55,65],[120,30,60],[65,18,52],[25,12,48],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,cf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(reaction)*0.05;
  const edge=1.0+(Math.abs(reaction)>0.65?0.18:0)+(Math.abs(reaction)>0.85?0.1:0);
  const hs=harm*0.08;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*cf)*lum*edge+hs*15))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*cf)*lum*edge-Math.abs(hs)*8))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*cf)*lum*edge+hs*12))|0
  ];
}
